-- ==============================================================================
-- BCA ICE CREAM WALA - 1-CLICK MOTHER DAIRY PRODUCTS & OFFICIAL IMAGES SCRIPT
-- Run this in your Supabase SQL Editor. Safe to run on live databases without data loss.
-- ==============================================================================

-- 1. Ensure display_order column exists on products
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS display_order INT DEFAULT 0;

-- 2. Ensure Mother Dairy Brand exists
VALUES ('a0000000-0000-0000-0000-000000000004', 'mother-dairy', 'Mother Dairy', 'Happy Food, Happy People', '/brands/mother-dairy.jpg', '#0284C7', 4)
ON CONFLICT (slug) DO UPDATE SET 
    name = EXCLUDED.name, 
    logo = EXCLUDED.logo, 
    color = EXCLUDED.color,
    tagline = EXCLUDED.tagline;

-- 3. Remove old Mother Dairy rows to prevent primary key or slug collisions
DELETE FROM public.daily_inventory WHERE product_id IN (SELECT id FROM public.products WHERE brand_slug = 'mother-dairy');
DELETE FROM public.order_items WHERE product_id IN (SELECT id FROM public.products WHERE brand_slug = 'mother-dairy');
DELETE FROM public.products WHERE brand_slug = 'mother-dairy';

-- 4. Insert All 82 Authentic Mother Dairy Products with Official motherdairy.com Images
-- (Notice: We omit the 'id' column so uuid_generate_v4() generates unique non-colliding UUIDs!)

-- 5. Ensure today's stock session has daily inventory for all 82 Mother Dairy products
DO $$
DECLARE
    v_session_id UUID;
    v_today_date DATE := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::DATE;
    p_rec RECORD;
BEGIN
    SELECT id INTO v_session_id FROM public.stock_sessions WHERE session_date = v_today_date LIMIT 1;
    
    IF v_session_id IS NULL THEN
        VALUES (v_today_date, 'published', 'Admin Store Manager', 'Daily inventory for all brands including Mother Dairy')
        RETURNING id INTO v_session_id;
    END IF;

    FOR p_rec IN SELECT id FROM public.products WHERE brand_slug = 'mother-dairy' LOOP
        VALUES (v_session_id, p_rec.id, 30, 0, 0, 5)
        ON CONFLICT (stock_session_id, product_id) DO UPDATE SET 
            published_quantity = EXCLUDED.published_quantity;
    END LOOP;
END $$;
